  const SEANS_OPT = [...H.SEANS.map((x) => ({ value: x.id, label: `${x.name} (${x.start}-${x.end})` })), { value: 'tam', label: 'Tüm gün' }];
  const by = () => (NS.currentUser || {}).name || '';
