    const rows = () => { const od = P(); const kal = (e) => H.toplam(e).genel - (od.get(e.id) || 0); return db.all('events', (e) => (f === 'tum' || (f === 'gelecek' ? e.date >= today() && e.status !== 'iptal' : f === 'opsiyon' ? e.status === 'opsiyon' : f === 'borc' ? ['kesin', 'tamam'].includes(e.status) && kal(e) > 0 : f === 'gecmis' ? e.date < today() && e.status !== 'iptal' : e.status === 'iptal')) && NS.match(q, e.no, cust(e.customer).name, cust(e.customer).phone)).sort((a, b) => a.date.localeCompare(b.date)); };
    const draw = () => { const r = rows(); $('#t', el).innerHTML = table({ rows: r, emptyIcon: 'calendar', empty: 'Bu görünümde etkinlik yok', columns: [{ label: 'No', render: (e) => `<span class="mono">${esc(e.no)}</span>` }, { label: 'Müşteri', render: (e) => `<b>${esc(cust(e.customer).name)}</b><div class="small faint">${esc(e.type)} · ${e.guests} kişi</div>` }, { label: 'Tarih', render: (e) => `${NS.date(e.date)}<div class="small faint">${esc(seansAd(e.seans))} · ${esc(hall(e.hall).name)}</div>` }, { label: 'Durum', render: durum }, ...(finans() ? [{ label: 'Toplam', cls: 'right', render: (e) => money(H.toplam(e).genel) }, { label: 'Kalan', cls: 'right', render: (e) => { const k = pay(e).kalan; return k > 0 ? `<b style="color:var(--warn)">${money(k)}</b>` : '-'; } }] : [])], actions: [{ icon: 'eye', act: 'v', title: 'Aç' }], foot: `${r.length} etkinlik` }); };
    $('#q', el).oninput = (e) => { q = e.target.value; draw(); };
    on(el, 'click', '[data-f]', (e, b) => { f = b.dataset.f; $$('[data-f]', el).forEach((x) => x.classList.toggle('active', x === b)); draw(); });
